package com.dormfix.maintenance.api;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/** The object key is generated by the server, so the client does not send one here. */
@JsonIgnoreProperties(ignoreUnknown = false)
public record PresignUploadRequest(@NotBlank String type,
        @NotBlank @Size(max = 255) String originalFilename,
        @NotBlank @Size(max = 100) String contentType, @NotNull Long fileSize) { }
